import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  random,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// --- Helper Components ---

const Cursor: React.FC<{ color: string }> = ({ color }) => {
  const frame = useCurrentFrame();
  const opacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;
  return (
    <span
      style={{
        display: "inline-block",
        width: 12,
        height: 32,
        backgroundColor: color,
        marginLeft: 4,
        opacity,
        verticalAlign: "middle",
        boxShadow: `0 0 8px ${color}`,
      }}
    />
  );
};

const NeuralBackground: React.FC<{ color: string; width: number; height: number }> = ({
  color,
  width,
  height,
}) => {
  const nodes = useMemo(() => {
    return new Array(20).fill(0).map((_, i) => ({
      x: random(i * 123) * width,
      y: random(i * 456) * height,
      r: random(i * 789) * 4 + 2,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill style={{ zIndex: 0, opacity: 0.15 }}>
      <svg width={width} height={height}>
        {nodes.map((node, i) => (
          <React.Fragment key={i}>
            <circle cx={node.x} cy={node.y} r={node.r} fill={color} />
            {nodes.slice(i + 1, i + 3).map((target, j) => (
              <line
                key={j}
                x1={node.x}
                y1={node.y}
                x2={target.x}
                y2={target.y}
                stroke={color}
                strokeWidth={1}
                opacity={0.5}
              />
            ))}
          </React.Fragment>
        ))}
      </svg>
    </AbsoluteFill>
  );
};

const BarChart: React.FC<{ color: string; delay: number }> = ({ color, delay }) => {
  const frame = useCurrentFrame();
  const bars = [0.4, 0.8, 0.3, 0.9, 0.6, 0.2, 0.7];

  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: 8, height: 60 }}>
      {bars.map((h, i) => {
        const seed = i * 99 + delay;
        // Jitter effect
        const jitter = Math.sin(frame * 0.5 + seed) * 0.1;
        const currentH = Math.max(0.1, h + jitter);
        
        const growth = spring({
          frame: frame - delay - (i * 2),
          fps: 30,
          config: { damping: 12 },
        });

        return (
          <div
            key={i}
            style={{
              width: 12,
              height: `${currentH * 100 * growth}%`,
              backgroundColor: color,
              opacity: 0.8,
              boxShadow: `0 0 5px ${color}`,
            }}
          />
        );
      })}
    </div>
  );
};

// --- Main Component ---



export type AISystemDemoProps = Record<string, any>;

const AISystemDemo: React.FC<AISystemDemoProps> = ({
  backgroundColor = "#050505",
  primaryColor = "#00FF41", // Neon Matrix Green
  accentColor = "#0AFFC9", // Cyber Cyan
  transparentBackground = false,
  durationInSeconds = 12,
  promptText = "Explain quantum entanglement like I'm five.",
  slamWords = ["MATCHING", "PREDICTING", "NOT THINKING"],
  answerText = "Imagine you have two magic dice. No matter how far apart they are, if you roll a 6 on one, the other instantly shows a 6 too.",
}) => {
  // Load Fonts
  useFontLoader(["JetBrains Mono", "Inter"]);

  const { fps, width, height } = useVideoConfig();
  const frame = useCurrentFrame();
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings
  const typeDuration = 45;
  const enterTapFrame = 50;
  const glitchStart = 55;
  const dashboardStart = 70;
  const slamStart = 100;
  const slamInterval = 35;
  const reassembleStart = slamStart + (slamWords.length * slamInterval) + 20;

  // --- Phase 1: Typing ---
  const charsToShow = Math.floor(
    interpolate(frame, [0, typeDuration], [0, promptText.length], {
      extrapolateRight: "clamp",
    })
  );
  const currentPrompt = promptText.substring(0, charsToShow);

  // --- Phase 2: Glitch / Shatter ---
  const glitchProgress = spring({
    frame: frame - glitchStart,
    fps,
    config: { stiffness: 200, damping: 5 },
  });
  
  // Random shake during glitch
  const shakeX = frame > glitchStart && frame < glitchStart + 15 
    ? (random(frame) - 0.5) * 40 
    : 0;
  const shakeY = frame > glitchStart && frame < glitchStart + 15 
    ? (random(frame + 1) - 0.5) * 40 
    : 0;

  const promptOpacity = interpolate(frame, [glitchStart, glitchStart + 10], [1, 0]);

  // --- Phase 3: Dashboard / Neural ---
  const dashboardOpacity = interpolate(frame, [dashboardStart, dashboardStart + 20], [0, 1]);

  // --- Phase 4: Slam Words ---
  // Renders inside main return

  // --- Phase 5: Reassembly (Token Stream) ---
  const answerWords = useMemo(() => answerText.split(" "), [answerText]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "JetBrains Mono",
        color: "#fff",
        overflow: "hidden",
      }}
    >
      {/* Background Neural Network - Always active but fades in/out */}
      <div style={{ opacity: interpolate(frame, [0, 60], [0, 1]) }}>
        <NeuralBackground color={primaryColor} width={width} height={height} />
      </div>

      {/* --- SAFE ZONE CONTAINER --- */}
      <AbsoluteFill
        style={{
          paddingTop: height * 0.15,
          paddingBottom: height * 0.1,
          paddingLeft: width * 0.08,
          paddingRight: width * 0.08,
          transform: `translate(${shakeX}px, ${shakeY}px)`,
        }}
      >
        {/* PROMPT SECTION */}
        <div style={{ opacity: promptOpacity, position: 'relative', zIndex: 10 }}>
          <h2
            style={{
              fontSize: 42,
              fontWeight: 400,
              color: "#aaa",
              marginBottom: 20,
              margin: 0,
            }}
          >
            USER_INPUT {'>'}
          </h2>
          <div
            style={{
              fontSize: 56,
              lineHeight: 1.3,
              color: primaryColor,
              textShadow: `0 0 15px ${primaryColor}66`,
            }}
          >
            {currentPrompt}
            <Cursor color={primaryColor} />
          </div>
        </div>

        {/* DASHBOARD OVERLAY */}
        <div
            style={{
                opacity: dashboardOpacity,
                position: 'absolute',
                top: height * 0.25,
                left: width * 0.08,
                right: width * 0.08,
                display: 'flex',
                flexDirection: 'column',
                gap: 40,
            }}
        >
            {/* Top Row Metrics */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                <div>
                    <div style={{ fontSize: 24, color: accentColor, marginBottom: 8 }}>TOKEN_PROBABILITY</div>
                    <BarChart color={accentColor} delay={dashboardStart} />
                </div>
                <div style={{ textAlign: 'right' }}>
                    <div style={{ fontSize: 24, color: primaryColor, marginBottom: 8 }}>CONFIDENCE</div>
                    <div style={{ fontSize: 60, fontWeight: 'bold', color: "#fff" }}>
                        {Math.min(99, Math.floor(interpolate(frame, [dashboardStart, dashboardStart + 60], [0, 99])))}%
                    </div>
                </div>
            </div>

            {/* Scrolling Code / Hex Dump Effect */}
            <div style={{ 
                fontFamily: 'JetBrains Mono', 
                fontSize: 18, 
                color: '#444', 
                height: 200, 
                overflow: 'hidden',
                maskImage: 'linear-gradient(to bottom, black 0%, transparent 100%)' 
            }}>
                {new Array(10).fill(0).map((_, i) => (
                    <div key={i} style={{ marginBottom: 4 }}>
                        0x{Math.floor(random(frame + i) * 1000000).toString(16).toUpperCase()} 
                        :: PROCESS_NODE_{i} 
                        :: {Math.random() > 0.5 ? 'ACTIVE' : 'IDLE'}
                    </div>
                ))}
            </div>
        </div>

        {/* SLAM WORDS - Centered Big Text */}
        {slamWords.map((word, index) => {
            const startFrame = slamStart + (index * slamInterval);
            const active = frame >= startFrame;
            
            // Spring animation for entrance
            const spr = spring({
                frame: frame - startFrame,
                fps,
                config: { stiffness: 300, damping: 15 }
            });

            // Exit animation when next word comes or final sequence starts
            const exitFrame = startFrame + slamInterval; 
            const exit = interpolate(frame, [exitFrame - 5, exitFrame], [1, 0], { extrapolateRight: 'clamp' });
            
            // Only show one at a time roughly, or stack them? 
            // Request says "one by one", usually implies replacing or overlaying. 
            // Let's overlay but fade out the previous.
            
            if (!active || frame > reassembleStart) return null;

            return (
                <div
                    key={index}
                    style={{
                        position: 'absolute',
                        top: '40%',
                        left: 0,
                        width: '100%',
                        textAlign: 'center',
                        opacity: exit,
                        transform: `scale(${interpolate(spr, [0, 1], [3, 1])})`,
                    }}
                >
                    <div style={{
                        fontFamily: 'Inter',
                        fontWeight: 900,
                        fontSize: 110,
                        color: "#fff",
                        textTransform: 'uppercase',
                        letterSpacing: -4,
                        textShadow: `0 0 40px ${primaryColor}`,
                        backgroundColor: '#000000aa', // slight backdrop
                        padding: '20px 0',
                    }}>
                        {word}
                    </div>
                    <div style={{ 
                        fontSize: 24, 
                        color: primaryColor, 
                        marginTop: 10,
                        letterSpacing: 10 
                    }}>
                        PROCESSING
                    </div>
                </div>
            );
        })}

        {/* FINAL ANSWER - Token Assembly */}
        {frame > reassembleStart && (
             <div style={{ 
                 marginTop: height * 0.1, // Push down a bit
                 display: 'flex', 
                 flexWrap: 'wrap', 
                 gap: '16px 24px',
                 justifyContent: 'flex-start'
            }}>
                {answerWords.map((word, i) => {
                    const wordStart = reassembleStart + (i * 3);
                    const spr = spring({
                        frame: frame - wordStart,
                        fps,
                        config: { stiffness: 180, damping: 12 }
                    });

                    // Random start positions
                    const startX = (random(i) - 0.5) * width;
                    const startY = (random(i + 100) - 0.5) * height;
                    
                    const x = interpolate(spr, [0, 1], [startX, 0]);
                    const y = interpolate(spr, [0, 1], [startY, 0]);
                    const opacity = interpolate(spr, [0, 1], [0, 1]);
                    const blur = interpolate(spr, [0, 1], [20, 0]);

                    // Highlight keywords (rudimentary logic: words > 6 chars)
                    const isHighlight = word.length > 6;

                    return (
                        <div
                            key={i}
                            style={{
                                transform: `translate(${x}px, ${y}px)`,
                                opacity,
                                filter: `blur(${blur}px)`,
                                fontSize: 48,
                                fontWeight: isHighlight ? 700 : 400,
                                color: isHighlight ? accentColor : "#fff",
                                textShadow: isHighlight ? `0 0 15px ${accentColor}` : 'none',
                                fontFamily: isHighlight ? "JetBrains Mono" : "Inter"
                            }}
                        >
                            {word}
                        </div>
                    );
                })}
             </div>
        )}

      </AbsoluteFill>
      
      {/* GLITCH OVERLAY (Flash) */}
      <AbsoluteFill
        style={{
            backgroundColor: "#fff",
            // FIX: Added a middle step to inputRange so it matches outputRange length (3)
            opacity: interpolate(frame, [glitchStart, glitchStart + 2.5, glitchStart + 5], [0, 0.2, 0]),
            pointerEvents: 'none',
            mixBlendMode: 'overlay',
        }}
      />
    </AbsoluteFill>
  );
};

export default AISystemDemo;